import React, { useState, useEffect, useCallback } from 'react';
import { Card, Button, Input, Alert, api } from '../App';

export default function MappingPage() {
  const [parties,       setParties]       = useState([]);
  const [gardens,       setGardens]       = useState([]);
  const [allGrades,     setAllGrades]     = useState([]);
  const [selected,      setSelected]      = useState(null);
  const [mappedGardens, setMappedGardens] = useState([]);
  const [gradeSamples,  setGradeSamples]  = useState({});
  const [search,        setSearch]        = useState('');
  const [gSearch,       setGSearch]       = useState('');
  const [saving,        setSaving]        = useState(false);
  const [alert,         setAlert]         = useState(null);
  const [addMode,       setAddMode]       = useState(false);
  const [newParty,      setNewParty]      = useState({ name: '', code: '' });
  const [tab,           setTab]           = useState('gardens');
  const [importing,     setImporting]     = useState(false);
  const [importResult,  setImportResult]  = useState(null);

  const load = useCallback(async () => {
    const [p, g, gr] = await Promise.all([
      api.get('/mapping/summary/all').catch(() => ({ data: [] })),
      api.get('/mapping/gardens').catch(() => ({ data: [] })),
      api.get('/marking/grades/list').catch(() => ({ data: [] }))
    ]);
    setParties(p.data);
    setGardens(g.data);
    setAllGrades(gr.data);
  }, []);

  useEffect(() => { load(); }, [load]);

  const selectParty = async (p) => {
    setSelected(p); setAlert(null);
    const [gRes, gsRes] = await Promise.all([
      api.get(`/mapping/${p.id}`).catch(() => ({ data: [] })),
      api.get(`/mapping/grade-samples/${p.id}`).catch(() => ({ data: {} }))
    ]);
    setMappedGardens(gRes.data.map(x => x.garden));
    setGradeSamples(gsRes.data || {});
  };

  const toggleGarden = (g) =>
    setMappedGardens(m => m.includes(g) ? m.filter(x => x !== g) : [...m, g]);

  const setSampleCount = (grade, count) =>
    setGradeSamples(s => ({ ...s, [grade]: count === '' ? undefined : parseInt(count) || 0 }));

  const saveAll = async () => {
    if (!selected) return;
    setSaving(true);
    try {
      await Promise.all([
        api.post('/mapping', { party_id: selected.id, gardens: mappedGardens }),
        api.post('/mapping/grade-samples', { party_id: selected.id, grade_samples: gradeSamples })
      ]);
      setAlert({ msg: `✅ Saved ${mappedGardens.length} gardens and grade settings for ${selected.party_name}`, type: 'success' });
      load();
    } catch (e) {
      setAlert({ msg: '❌ ' + (e.response?.data?.error || e.message), type: 'error' });
    } finally { setSaving(false); }
  };

  const addParty = async () => {
    if (!newParty.name || !newParty.code) { setAlert({ msg: 'Party name and code required', type: 'error' }); return; }
    try {
      await api.post('/parties', { party_name: newParty.name, party_code: newParty.code });
      setNewParty({ name: '', code: '' }); setAddMode(false); load();
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
  };

  const delParty = async (id, name) => {
    if (!window.confirm(`Delete "${name}"? Removes all mappings.`)) return;
    await api.delete(`/parties/${id}`);
    setSelected(null); setMappedGardens([]); setGradeSamples({}); load();
  };

  const importParties = async (file) => {
    setImporting(true); setImportResult(null);
    const fd = new FormData(); fd.append('file', file);
    try {
      const r = await api.post('/mapping/import-parties', fd);
      setImportResult(r.data); load();
    } catch (e) { setImportResult({ error: e.response?.data?.error || e.message }); }
    finally { setImporting(false); }
  };

  // ── Derived values (computed inline, not hoisted to end-of-function) ────────
  const filteredParties = parties.filter(p =>
    p.party_name.toLowerCase().includes(search.toLowerCase()) ||
    p.party_code.toLowerCase().includes(search.toLowerCase())
  );
  const filteredGardens = gardens.filter(g => g.toLowerCase().includes(gSearch.toLowerCase()));

  const chipStyle = (sel) => ({
    padding: '5px 12px', borderRadius: 20, cursor: 'pointer', fontSize: 12, fontWeight: 600,
    border: `1.5px solid ${sel ? '#1a7a4a' : '#e2e8f0'}`,
    background: sel ? '#dcfce7' : '#f9fafb',
    color: sel ? '#166534' : '#555',
    userSelect: 'none', transition: 'all 0.1s'
  });

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>🔗 Party Mapping</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 20 }}>
        Map parties to gardens and set sample count per grade. Import from PC.xlsx.
      </p>

      {alert && <Alert msg={alert.msg} type={alert.type} />}

      <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start' }}>

        {/* ── LEFT: Party list ───────────────────────────────────────────── */}
        <Card style={{ width: 290, minWidth: 270, flexShrink: 0 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
            <h3 style={{ fontSize: 14 }}>Parties ({filteredParties.length})</h3>
            <div style={{ display: 'flex', gap: 6 }}>
              <Button size="sm" variant="outline"
                onClick={() => document.getElementById('party-import-input').click()}
                style={{ fontSize: 11, padding: '4px 8px' }}>
                {importing ? '…' : '📥 Import'}
              </Button>
              <input id="party-import-input" type="file" accept=".xlsx,.xls" style={{ display: 'none' }}
                onChange={e => { if (e.target.files[0]) importParties(e.target.files[0]); e.target.value = ''; }} />
              <Button size="sm" onClick={() => setAddMode(!addMode)}>+ Add</Button>
            </div>
          </div>

          {importResult && (
            <div style={{ fontSize: 12, padding: '6px 10px', borderRadius: 6, marginBottom: 10,
              background: importResult.error ? '#fee2e2' : '#f0fdf4',
              color: importResult.error ? '#991b1b' : '#166534' }}>
              {importResult.error ? `❌ ${importResult.error}` : `✅ Imported ${importResult.imported} parties`}
            </div>
          )}

          {addMode && (
            <div style={{ background: '#f0f8ff', padding: 12, borderRadius: 6, marginBottom: 12 }}>
              <Input label="Party Name" value={newParty.name}
                onChange={v => setNewParty(p => ({ ...p, name: v }))} placeholder="e.g. ASHA" />
              <Input label="Party Code" value={newParty.code}
                onChange={v => setNewParty(p => ({ ...p, code: v }))} placeholder="e.g. AA" />
              <div style={{ display: 'flex', gap: 8 }}>
                <Button size="sm" variant="success" onClick={addParty}>Save</Button>
                <Button size="sm" variant="outline" onClick={() => setAddMode(false)}>Cancel</Button>
              </div>
            </div>
          )}

          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search parties…"
            style={{ width: '100%', padding: '6px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 12, marginBottom: 8 }} />

          <div style={{ maxHeight: 520, overflowY: 'auto' }}>
            {filteredParties.length === 0 && (
              <div style={{ color: '#aaa', fontSize: 13, padding: 12, textAlign: 'center' }}>
                {parties.length === 0 ? 'No parties. Import PC.xlsx or click + Add.' : 'No match.'}
              </div>
            )}
            {filteredParties.map(p => (
              <div key={p.id} onClick={() => selectParty(p)}
                style={{ padding: '7px 10px', borderRadius: 6, cursor: 'pointer', marginBottom: 3,
                  background: selected?.id === p.id ? '#dbeafe' : '#f9fafb',
                  border: `1.5px solid ${selected?.id === p.id ? '#93c5fd' : 'transparent'}`,
                  display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <div style={{ fontWeight: 700, fontSize: 12 }}>{p.party_name}</div>
                  <div style={{ fontSize: 10, color: '#888' }}>{p.party_code} · {p.garden_count || 0} gardens</div>
                </div>
                <button onClick={e => { e.stopPropagation(); delParty(p.id, p.party_name); }}
                  style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#ddd', fontSize: 12 }}>✕</button>
              </div>
            ))}
          </div>
        </Card>

        {/* ── RIGHT: Gardens + Grade mapping ────────────────────────────── */}
        <div style={{ flex: 1 }}>
          {!selected
            ? <Card style={{ textAlign: 'center', padding: 40, color: '#aaa' }}>Select a party to manage mappings</Card>
            : (
              <Card>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
                  <div>
                    <h3 style={{ fontSize: 15 }}>{selected.party_name}</h3>
                    <div style={{ fontSize: 12, color: '#888' }}>{selected.party_code} · {mappedGardens.length} gardens</div>
                  </div>
                  <Button variant="success" onClick={saveAll} disabled={saving}>
                    {saving ? 'Saving…' : '💾 Save All'}
                  </Button>
                </div>

                {/* Tabs */}
                <div style={{ display: 'flex', borderBottom: '2px solid #e2e8f0', marginBottom: 14 }}>
                  {[
                    { key: 'gardens', label: `🌿 Gardens (${mappedGardens.length} selected)` },
                    { key: 'grades',  label: `📊 Grade & Samples` }
                  ].map(t => (
                    <div key={t.key} onClick={() => setTab(t.key)}
                      style={{ padding: '7px 16px', cursor: 'pointer', fontSize: 13, fontWeight: 600,
                        color: tab === t.key ? '#1a3c5e' : '#888',
                        borderBottom: `2px solid ${tab === t.key ? '#1a3c5e' : 'transparent'}`,
                        marginBottom: -2 }}>
                      {t.label}
                    </div>
                  ))}
                </div>

                {/* GARDENS TAB */}
                {tab === 'gardens' && (
                  <>
                    <div style={{ display: 'flex', gap: 8, marginBottom: 10, alignItems: 'center' }}>
                      <input value={gSearch} onChange={e => setGSearch(e.target.value)} placeholder="Search gardens…"
                        style={{ flex: 1, padding: '7px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 13 }} />
                      <Button size="sm" variant="outline" onClick={() => setMappedGardens([...filteredGardens])}>All</Button>
                      <Button size="sm" variant="outline" onClick={() => setMappedGardens([])}>Clear</Button>
                    </div>
                    <div style={{ display: 'flex', gap: 7, flexWrap: 'wrap', maxHeight: 350, overflowY: 'auto' }}>
                      {filteredGardens.length === 0
                        ? <div style={{ color: '#aaa', fontSize: 13, padding: 12 }}>No gardens. Import a Catalogue first.</div>
                        : filteredGardens.map(g => (
                          <div key={g} onClick={() => toggleGarden(g)} style={chipStyle(mappedGardens.includes(g))}>
                            {mappedGardens.includes(g) ? '✓ ' : ''}{g}
                          </div>
                        ))
                      }
                    </div>
                    {mappedGardens.length > 0 && (
                      <div style={{ marginTop: 12, padding: 10, background: '#f0f8ff', borderRadius: 6 }}>
                        <div style={{ fontSize: 11, fontWeight: 700, color: '#1a3c5e', marginBottom: 4 }}>
                          Mapped ({mappedGardens.length}):
                        </div>
                        <div style={{ fontSize: 11, color: '#555', lineHeight: 1.8 }}>
                          {mappedGardens.sort().join(' · ')}
                        </div>
                      </div>
                    )}
                  </>
                )}

                {/* GRADES TAB */}
                {tab === 'grades' && (
                  <>
                    <div style={{ fontSize: 12, color: '#888', marginBottom: 12 }}>
                      Set the number of samples per grade. When marking, the system selects the top N lots for each grade from mapped gardens.
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 10 }}>
                      {allGrades.map(g => (
                        <div key={g} style={{ background: '#f8fafc', border: '1.5px solid #e2e8f0', borderRadius: 8, padding: '10px 14px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                          <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 8px', borderRadius: 99, fontSize: 12, fontWeight: 700 }}>
                            {g}
                          </span>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                            <span style={{ fontSize: 11, color: '#888' }}>Samples:</span>
                            <input
                              type="number" min="0" max="100"
                              value={gradeSamples[g] || ''}
                              onChange={e => setSampleCount(g, e.target.value)}
                              placeholder="0"
                              style={{ width: 55, padding: '4px 8px',
                                border: `1.5px solid ${gradeSamples[g] ? '#1a7a4a' : '#cbd5e0'}`,
                                borderRadius: 6, fontSize: 13, textAlign: 'center',
                                fontWeight: gradeSamples[g] ? 700 : 400,
                                color: gradeSamples[g] ? '#166534' : '#555' }}
                            />
                          </div>
                        </div>
                      ))}
                    </div>
                    <div style={{ marginTop: 12, padding: 10, background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 6, fontSize: 12, color: '#92400e' }}>
                      💡 Example: BOP = 10 means top 10 BOP lots from mapped gardens will appear in Marking.
                    </div>
                  </>
                )}
              </Card>
            )
          }
        </div>
      </div>
    </div>
  );
}
